// Package norm implements Unicode Normalization Form C (UAX #15) with the
// standard library only. It exists so that a backup passphrase typed in
// either precomposed (é = U+00E9) or decomposed (e + U+0301) form derives the
// same key, exactly like VaneSecret's pass.normalize('NFC').
//
// The data tables (tables.go) are generated by tools/gennorm/gennorm.py from
// Python's unicodedata; see UnicodeVersion. Code points unassigned in that
// version have no decomposition and ccc 0, so they are kept as they are.
package norm

import (
	"sort"
	"unicode/utf8"
)

// Hangul syllable constants (Unicode §3.12).
const (
	sBase  = 0xAC00
	lBase  = 0x1100
	vBase  = 0x1161
	tBase  = 0x11A7
	lCount = 19
	vCount = 21
	tCount = 28
	nCount = vCount * tCount
	sCount = lCount * nCount
)

func ccc(r rune) uint8 { return cccTable[r] }

// NFC returns s in Normalization Form C. Invalid UTF-8 bytes become U+FFFD.
func NFC(s string) string {
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= utf8.RuneSelf {
			ascii = false
			break
		}
	}
	if ascii {
		return s
	}
	return string(compose(reorder(decompose(s))))
}

// decompose applies the full canonical decomposition.
func decompose(s string) []rune {
	out := make([]rune, 0, len(s))
	for _, r := range s {
		if r >= sBase && r < sBase+sCount {
			i := r - sBase
			out = append(out, lBase+i/nCount, vBase+(i%nCount)/tCount)
			if t := i % tCount; t != 0 {
				out = append(out, tBase+t)
			}
			continue
		}
		if d, ok := decompTable[r]; ok {
			out = append(out, d...)
			continue
		}
		out = append(out, r)
	}
	return out
}

// reorder sorts every run of non-starters by ccc, stably (canonical ordering).
func reorder(rs []rune) []rune {
	for i := 0; i < len(rs); {
		if ccc(rs[i]) == 0 {
			i++
			continue
		}
		j := i
		for j < len(rs) && ccc(rs[j]) != 0 {
			j++
		}
		run := rs[i:j]
		sort.SliceStable(run, func(a, b int) bool { return ccc(run[a]) < ccc(run[b]) })
		i = j
	}
	return rs
}

func composePair(a, b rune) (rune, bool) {
	// Hangul LV and LVT.
	if a >= lBase && a < lBase+lCount && b >= vBase && b < vBase+vCount {
		return sBase + ((a-lBase)*vCount+(b-vBase))*tCount, true
	}
	if a >= sBase && a < sBase+sCount && (a-sBase)%tCount == 0 && b > tBase && b < tBase+tCount {
		return a + (b - tBase), true
	}
	c, ok := compTable[uint64(a)<<21|uint64(b)]
	return c, ok
}

// compose applies the canonical composition algorithm in place.
func compose(rs []rune) []rune {
	if len(rs) == 0 {
		return rs
	}
	starter := -1
	if ccc(rs[0]) == 0 {
		starter = 0
	}
	out := rs[:1]
	var last uint8 = ccc(rs[0])
	if starter == 0 {
		last = 0
	}
	for _, r := range rs[1:] {
		c := ccc(r)
		if starter >= 0 {
			// r is blocked from the starter if a character in between has
			// ccc 0 or ccc >= c. last is the ccc of the previous kept char,
			// or 0 when it is the starter itself (adjacent).
			adjacent := len(out)-1 == starter
			if adjacent || (last != 0 && last < c) {
				if p, ok := composePair(out[starter], r); ok {
					out[starter] = p
					continue
				}
			}
		}
		if c == 0 {
			starter = len(out)
			last = 0
		} else {
			last = c
		}
		out = append(out, r)
	}
	return out
}
